{
  "description": "The creature is a large composite quadruped standing in right-facing profile on a small patch of dry, sparsely grassed ground. The front half, including the head, neck, chest and two outspread wings, is that of a golden-brown eagle with a hooked beak, yellow eye, and dense layered plumage in shades of gold, tan, cream and dark brown, while the rear half, torso, four legs and long tail are that of a tawny lion with short smooth fur and muscular limbs. The two expansive wings are raised and spread wide above the back, showing detailed flight feathers, and the lion-like tail hangs down behind with a dark tuft at the tip. The overall impression is of a single griffin-like animal combining eagle and lion features in a naturalistic illustration style.",
  "parts": [
    {
      "part": "head",
      "looks_like": "eagle-like head at the front of the body facing right, covered in golden-brown feathers with a darker brown crown, a sharp hooked beak that is dark gray at the tip with a yellow cere and base, a yellow eye with a dark pupil and a fierce expression, and a small nostril visible on the beak",
      "where": "at the anterior end of the neck, above the feathered chest"
    },
    {
      "part": "mane",
      "looks_like": "thick ruff of elongated shaggy feathers in dark brown, golden-brown and cream, forming a lion-like mane around the lower neck and chest",
      "where": "encircling the front of the neck and hanging down over the upper chest between the front legs"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, muscular lion-like legs covered in short tawny tan fur with lighter underparts and darker shading at the joints, straight and weight-bearing",
      "where": "two front legs under the chest and two hind legs under the hips, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "large paw-like feet with rounded pads, light tan fur, and short dark claws visible at the toes",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long slender lion-like tail covered in short tawny fur with a distinct dark brown to black tuft of longer hair at the tip, slightly curved as it hangs",
      "where": "extending from the rear of the hindquarters, hanging down along the left side of the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two very large, broad feathered wings fully spread outward and upward, with layered feathers in golden-brown on the coverts, darker brown and gray-brown on the flight feathers, and detailed barring and edging on individual feathers",
      "where": "attached to the upper back behind the neck, one on the near side prominently visible and one on the far side partially visible behind it"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping plumage covering the head, neck, chest and wings, with small scale-like feathers on the chest and larger layered feathers on the wings in mixed shades of gold, tan, cream, and dark brown",
      "where": "covering the head, neck, chest, and entire surface of both wings"
    }
  ],
  "attached_objects": [],
  "animals": [
    "eagle",
    "lion"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
